package com.pab.modul7

import android.os.Bundle
import android.text.method.ScrollingMovementMethod
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.ImageView
import android.widget.TextView
import androidx.fragment.app.DialogFragment

class DetailDialogFragment : DialogFragment() {

    companion object {
        const val ARG_KAMPUS = "arg_kampus"

        fun newInstance(kampus: Kampus): DetailDialogFragment {
            val fragment = DetailDialogFragment()
            val args = Bundle()
            args.putParcelable(ARG_KAMPUS, kampus)
            fragment.arguments = args
            return fragment
        }
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View? {
        return inflater.inflate(R.layout.activity_detail, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        val toolbar = view.findViewById<androidx.appcompat.widget.Toolbar>(R.id.toolbar)
        toolbar.visibility = View.GONE

        val imgDetailPhoto: ImageView = view.findViewById(R.id.img_detail_photo)
        val tvDetailName: TextView = view.findViewById(R.id.tv_detail_name)
        val tvDetailLocation: TextView = view.findViewById(R.id.tv_detail_location)
        val tvDetailDescription: TextView = view.findViewById(R.id.tv_detail_description)

        tvDetailDescription.movementMethod = ScrollingMovementMethod()

        val kampus = arguments?.getParcelable<Kampus>(ARG_KAMPUS)
        if (kampus != null) {
            imgDetailPhoto.setImageResource(kampus.photo)
            tvDetailName.text = kampus.name
            tvDetailLocation.text = kampus.lokasi
            tvDetailDescription.text = kampus.sejarah
        }
    }

    override fun onStart() {
        super.onStart()
        dialog?.window?.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
    }
}
